<script>(()=>{const h=document.getElementById('site-header'),t=document.getElementById('menu-toggle'),m=document.getElementById('mobile-menu');const setMenu=o=>{m.classList.toggle('open',o);document.body.classList.toggle('menu-open',o);t.setAttribute('aria-expanded',String(o));t.setAttribute('aria-label',o?'Close menu':'Open menu');t.innerHTML=o?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16M4 12h16M4 17h16"/></svg>'};t.addEventListener('click',()=>setMenu(!m.classList.contains('open')));m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));const scroll=()=>h.classList.toggle('scrolled',scrollY>18);scroll();addEventListener('scroll',scroll,{passive:true});const els=document.querySelectorAll('[data-reveal]');if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion:reduce)').matches){els.forEach(e=>e.classList.add('revealed'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -35px'});els.forEach(e=>observer.observe(e))})();</script>
<script>(()=>{const counters=document.querySelectorAll('[data-count]');if(!counters.length)return;const complete=el=>{el.textContent=el.dataset.count+(el.dataset.suffix||'')};if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){counters.forEach(complete);return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target,target=Number(el.dataset.count),started=performance.now(),duration=900;const tick=now=>{const progress=Math.min((now-started)/duration,1),value=Math.round(target*(1-Math.pow(1-progress,3)));el.textContent=value+(el.dataset.suffix||'');if(progress<1)requestAnimationFrame(tick)};requestAnimationFrame(tick);observer.unobserve(el)}),{threshold:.6});counters.forEach(el=>observer.observe(el))})();</script>
<script>(()=>{const form=document.querySelector('.contact-form'),notice=document.getElementById('contact-notification');if(!form||!notice)return;const button=form.querySelector('button[type=submit]'),buttonHtml=button.innerHTML,icon=notice.querySelector('.contact-notification-icon'),title=notice.querySelector('strong'),message=notice.querySelector('p');let timer;const hide=()=>notice.classList.remove('is-visible');const show=(type,text)=>{clearTimeout(timer);const error=type==='error';notice.classList.toggle('is-error',error);icon.textContent=error?'!':'✓';title.textContent=error?'Could not send enquiry':'Enquiry sent';message.textContent=text;notice.classList.add('is-visible');timer=setTimeout(hide,6000)};notice.querySelector('button').addEventListener('click',hide);form.addEventListener('submit',async event=>{event.preventDefault();form.querySelectorAll('.contact-error').forEach(error=>error.remove());form.querySelectorAll('[aria-invalid=true]').forEach(input=>input.removeAttribute('aria-invalid'));button.disabled=true;button.textContent='Sending…';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json().catch(()=>({}));if(!response.ok){if(response.status===422&&data.errors){Object.entries(data.errors).forEach(([name,messages])=>{const input=form.elements.namedItem(name);if(!input)return;input.setAttribute('aria-invalid','true');const error=document.createElement('span');error.className='contact-error';error.textContent=messages[0];input.after(error)});show('error','Please check the highlighted details and try again.');return}throw new Error(data.message||'Unable to send your enquiry right now.')}form.reset();show('success',data.message||'Thanks! We’ll contact you shortly.')}catch(error){show('error',error.message||'Unable to send your enquiry right now.')}finally{button.disabled=false;button.innerHTML=buttonHtml}})})();</script>
<script>(()=>{const modal=document.getElementById('demo-request'),form=modal?.querySelector('.demo-request-form'),notice=document.getElementById('contact-notification');if(!modal||!form||!notice)return;const panel=modal.querySelector('.demo-request-panel'),button=form.querySelector('button[type=submit]'),buttonHtml=button.innerHTML,noticeIcon=notice.querySelector('.contact-notification-icon'),noticeTitle=notice.querySelector('strong'),noticeMessage=notice.querySelector('p');let returnFocus=null,noticeTimer;const open=trigger=>{returnFocus=trigger;modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');document.body.classList.add('demo-modal-open');requestAnimationFrame(()=>form.querySelector('input')?.focus())};const close=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('demo-modal-open');returnFocus?.focus()};const showNotice=(type,text)=>{clearTimeout(noticeTimer);const error=type==='error';notice.classList.toggle('is-error',error);noticeIcon.textContent=error?'!':'✓';noticeTitle.textContent=error?'Could not send enquiry':'Demo requested';noticeMessage.textContent=text;notice.classList.add('is-visible');noticeTimer=setTimeout(()=>notice.classList.remove('is-visible'),6000)};document.querySelectorAll('a[href="#demo-request"]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();open(link)}));modal.querySelectorAll('[data-demo-modal-close]').forEach(control=>control.addEventListener('click',close));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.classList.contains('is-open'))close();if(event.key==='Tab'&&modal.classList.contains('is-open')){const focusable=[...panel.querySelectorAll('button,input')].filter(element=>!element.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});form.addEventListener('submit',async event=>{event.preventDefault();form.querySelectorAll('.contact-error').forEach(error=>error.remove());form.querySelectorAll('[aria-invalid=true]').forEach(input=>input.removeAttribute('aria-invalid'));button.disabled=true;button.textContent='Sending…';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json().catch(()=>({}));if(!response.ok){if(response.status===422&&data.errors){Object.entries(data.errors).forEach(([name,messages])=>{const input=form.elements.namedItem(name);if(!input)return;input.setAttribute('aria-invalid','true');const error=document.createElement('span');error.className='contact-error';error.textContent=messages[0];input.after(error)});showNotice('error','Please check the highlighted details and try again.');return}throw new Error(data.message||'Unable to send your request right now.')}form.reset();close();showNotice('success',data.message||'Thanks! We’ll contact you shortly.')}catch(error){showNotice('error',error.message||'Unable to send your request right now.')}finally{button.disabled=false;button.innerHTML=buttonHtml}})})();</script>
